package incremental
import("encoding/json";"errors";"io";"os";"path/filepath";"sort";"strings")
type Rule struct{CheckID string `json:"check_id"`;Patterns []string `json:"patterns"`}
type Input struct{SchemaVersion string `json:"schema_version"`;ChangedPaths []string `json:"changed_paths"`;TrustedChecks []string `json:"trusted_checks"`;Rules []Rule `json:"rules"`;Release bool `json:"release"`}
type Selection struct{SchemaVersion string `json:"schema_version"`;Mode string `json:"mode"`;Checks []string `json:"checks"`;Reason string `json:"reason,omitempty"`}
func Load(path string)(Input,error){f,err:=os.Open(path);if err!=nil{return Input{},err};defer f.Close();d:=json.NewDecoder(f);d.DisallowUnknownFields();var in Input;if err:=d.Decode(&in);err!=nil{return in,err};var x any;if err:=d.Decode(&x);!errors.Is(err,io.EOF){return in,errors.New("unexpected trailing JSON")};return in,nil}
func Select(in Input)(Selection,error){if in.SchemaVersion!="1.0.0"||len(in.TrustedChecks)==0{return Selection{},errors.New("incremental input is incomplete")};trustedSeen:=map[string]bool{};for _,id:=range in.TrustedChecks{if strings.TrimSpace(id)==""||trustedSeen[id]{return Selection{},errors.New("trusted check ids must be unique and nonempty")};trustedSeen[id]=true};ruleSeen:=map[string]bool{};for _,r:=range in.Rules{if strings.TrimSpace(r.CheckID)==""||ruleSeen[r.CheckID]||len(r.Patterns)==0{return Selection{},errors.New("impact rule ids and patterns must be unique and nonempty")};ruleSeen[r.CheckID]=true;patternSeen:=map[string]bool{};for _,p:=range r.Patterns{if strings.TrimSpace(p)==""||patternSeen[p]{return Selection{},errors.New("impact rule patterns must be unique and nonempty")};patternSeen[p]=true}};if in.Release{return full(in,"release mode requires full verification"),nil};if len(in.ChangedPaths)==0{return full(in,"empty changed scope requires full verification"),nil};picked:=map[string]bool{};for _,p:=range in.ChangedPaths{clean:=filepath.Clean(p);if p==""||filepath.IsAbs(p)||clean==".."||strings.HasPrefix(clean,"../"){return full(in,"changed path escapes repository"),nil};matches:=[]string{};for _,r:=range in.Rules{for _,pattern:=range r.Patterns{ok,err:=filepath.Match(pattern,clean);if err!=nil{return Selection{},err};if ok{matches=append(matches,r.CheckID);break}}};if len(matches)!=1{return full(in,"changed path impact is unknown or ambiguous"),nil};picked[matches[0]]=true};checks:=[]string{};trusted:=map[string]bool{};for _,c:=range in.TrustedChecks{trusted[c]=true};for c:=range picked{if !trusted[c]{return full(in,"mapped check is not trusted"),nil};checks=append(checks,c)};sort.Strings(checks);if len(checks)==0{return full(in,"empty selected check set requires full verification"),nil};return Selection{SchemaVersion:"1.0.0",Mode:"incremental",Checks:checks},nil}
func full(in Input,reason string)Selection{checks:=append([]string{},in.TrustedChecks...);sort.Strings(checks);return Selection{SchemaVersion:"1.0.0",Mode:"full",Checks:checks,Reason:reason}}
